test('bulk discount with tier discount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.ok(totals.discount > 0);
});

test('VAT calculated after bulk discount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);

  const lineTot = firstProduct.unitPrice * 10;
  const bulkDiscount = Math.round((lineTot * 2.5) / 100);
  const afterDiscount = lineTot - bulkDiscount;
  const expectedVAT = Math.round((afterDiscount * firstProduct.vatRate) / 100);

  assert.equal(totals.vat, expectedVAT);
});

test('bulk discount with multiple lines', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: firstProduct.sku, qty: 10, discountPercent: 0 },
      { sku: firstProduct.sku, qty: 9, discountPercent: 0 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  // Only first line should get bulk discount
  const line1Tot = firstProduct.unitPrice * 10;
  const line1BulkDiscount = Math.round((line1Tot * 2.5) / 100);

  assert.ok(totals.discount >= line1BulkDiscount);
});

test('bulk discount reflected in total', () => {
  const invoice1 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 5, discountPercent: 0 }],
  }).value;

  const invoice2 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 0 }],
