    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-01-01',
      lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 0 }],
    }).value,
    []
  ).value;

  const totals = invoiceTotals(invoice);

  assert.ok(totals.subtotal > 0);
  assert.ok(totals.total > 0);
});

test('bulk discount applies to lines with qty >= 10', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const lineTot = firstProduct.unitPrice * 10;

  // Bulk discount: 2.5% of line total
  const expectedBulkDiscount = Math.round((lineTot * 2.5) / 100);

  assert.ok(totals.discount >= expectedBulkDiscount);
});

test('bulk discount does not apply to lines with qty < 10', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 9, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const lineTot = firstProduct.unitPrice * 9;

  // Should have no bulk discount (2.5%), but might have tier discount
  // Bulk discount would be 2.5% of lineTot, so check it's not there
  const bulkDiscount = Math.round((lineTot * 2.5) / 100);
  assert.equal(totals.discount, 0); // explicit 0 discount means no tier discount either
});

test('bulk discount is applied after line discount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);

  const lineTot = firstProduct.unitPrice * 10;
  const lineDiscount = Math.round((lineTot * 10) / 100);
  const afterLineDiscount = lineTot - lineDiscount;
  const bulkDiscount = Math.round((afterLineDiscount * 2.5) / 100);
  const totalDiscount = lineDiscount + bulkDiscount;

  assert.equal(totals.discount, totalDiscount);
});

