  assert.ok(totals.discount >= line1BulkDiscount);
});

test('bulk discount reflected in total', () => {
  // Compare quantities where bulk discount makes the difference
  const invoiceSmall = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 0 }],
