  const totalsSmall = invoiceTotals(invoiceSmall);
  const totalsLarge = invoiceTotals(invoiceLarge);

  // Both have bulk discount, but larger quantity should have larger absolute discount
  assert.ok(totalsLarge.discount > totalsSmall.discount);
});

test('bulk discount with large quantity', () => {
