  assert.ok(Number.isInteger(totals.discount));
  assert.ok(Number.isInteger(totals.vat));
  assert.ok(Number.isInteger(totals.total));
});

test('bulk discount combined with line and tier discounts', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 10, discountPercent: 5 }],
  }).value;

  const totals = invoiceTotals(invoice);

  const lineTot = firstProduct.unitPrice * 10;
  const lineDiscount = Math.round((lineTot * 5) / 100);
  const afterLineDiscount = lineTot - lineDiscount;
  const bulkDiscount = Math.round((afterLineDiscount * 2.5) / 100);

  assert.ok(totals.discount >= lineDiscount + bulkDiscount);
});

