    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-01-31');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-01-31');
});

test('createInvoice EOM term handles month-end dates', () => {
  assert.equal(
    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-02-28',
      lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
      terms: 'EOM',
    }).value.dueDate,
    '2026-02-28'
  );

  assert.equal(
    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-04-30',
      lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
      terms: 'EOM',
    }).value.dueDate,
    '2026-04-30'
  );
});

test('createInvoice EOM term handles leap year February', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2024-02-15',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
    terms: 'EOM',
  });

  assert.equal(result.value.dueDate, '2024-02-29');
});

test('createInvoice rejects invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-01-01',
      lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
      terms: 'INVALID',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );

  assert.deepEqual(
    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-01-01',
      lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
      terms: 'net30',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

test('applyVoucher requires draft status', () => {
  const issued = issueInvoice(
    createInvoice({
      customerId: firstCustomer.id,
      issueDate: '2026-01-01',
      lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
    }).value,
    []
  ).value;

  assert.deepEqual(applyVoucher(issued, { code: 'SAVE10', amount: 500 }), {
    ok: false,
    error: 'NOT_DRAFT',
  });
});

test('applyVoucher stores code and amount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const result = applyVoucher(invoice, { code: 'SUMMER2026', amount: 1000 });

  assert.equal(result.ok, true);
  assert.equal(result.value.voucher.code, 'SUMMER2026');
  assert.equal(result.value.voucher.amount, 1000);
});

test('applyVoucher rejects duplicate vouchers', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const result1 = applyVoucher(invoice, { code: 'FIRST', amount: 500 });
  assert.equal(result1.ok, true);

  const result2 = applyVoucher(result1.value, { code: 'SECOND', amount: 300 });
  assert.deepEqual(result2, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher validates amount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  assert.deepEqual(applyVoucher(invoice, { code: 'TEST', amount: 0 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });

  assert.deepEqual(applyVoucher(invoice, { code: 'TEST', amount: -100 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });

  assert.deepEqual(applyVoucher(invoice, { code: 'TEST', amount: 100.5 }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });

  assert.deepEqual(applyVoucher(invoice, { code: 'TEST', amount: 'abc' }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
});

test('applyVoucher does not mutate input invoice', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  applyVoucher(invoice, { code: 'TEST', amount: 500 });

  assert.equal(Object.hasOwn(invoice, 'voucher'), false);
});

test('invoiceTotals includes voucher amount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.voucher, 500);
});

test('invoiceTotals calculates total with voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.total, totals.subtotal + totals.vat - totals.voucher);
});

test('invoiceTotals with discount, vat, and voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 20 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'FINAL', amount: 1000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals clamps total at 0 with large voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const totals1 = invoiceTotals(invoice);
  const largeVoucher = totals1.total + 10000;

  const withVoucher = applyVoucher(invoice, { code: 'MASSIVE', amount: largeVoucher }).value;
  const totals2 = invoiceTotals(withVoucher);

  assert.equal(totals2.total, 0);
});

test('invoiceTotals without voucher returns 0 voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.voucher, 0);
});

