import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { listCustomers } from '../src/customers.js';
import { listProducts } from '../src/catalogue.js';

const firstCustomer = listCustomers()[0];
const firstProduct = listProducts()[0];

test('createInvoice requires a non-empty lines array', () => {
  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [],
  }), { ok: false, error: 'NO_LINES' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: null,
  }), { ok: false, error: 'NO_LINES' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: undefined,
  }), { ok: false, error: 'NO_LINES' });
});

test('createInvoice validates issueDate format', () => {
  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026/01/01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '01-01-2026',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: 'not-a-date',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice validates date existence', () => {
  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2025-02-29',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2024-02-30',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice accepts leap year dates', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2024-02-29',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.issueDate, '2024-02-29');
});

test('createInvoice checks customer exists', () => {
  assert.deepEqual(createInvoice({
    customerId: 'NONEXISTENT',
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  }), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice validates qty is a positive integer', () => {
  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 0 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: -1 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1.5 }],
  }), { ok: false, error: 'QTY_INVALID' });

  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 'abc' }],
  }), { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice checks SKU exists in catalogue', () => {
  assert.deepEqual(createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: 'NONEXISTENT', qty: 1 }],
  }), { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, firstCustomer.id);
  assert.equal(result.value.issueDate, '2026-01-01');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);

  const line = result.value.lines[0];
  assert.equal(line.sku, firstProduct.sku);
  assert.equal(line.name, firstProduct.name);
  assert.equal(line.qty, 5);
  assert.equal(line.unitPrice, firstProduct.unitPrice);
  assert.equal(line.vatRate, firstProduct.vatRate);
});

test('createInvoice handles multiple lines', () => {
  const products = listProducts();
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: products[0].sku, qty: 2 },
      { sku: products[1].sku, qty: 3 },
      { sku: products[2].sku, qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[2].qty, 1);
});

test('createInvoice does not mutate input', () => {
  const inputLines = [{ sku: firstProduct.sku, qty: 1 }];
  const inputLinesCopy = JSON.parse(JSON.stringify(inputLines));

  createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: inputLines,
  });

  assert.deepEqual(inputLines, inputLinesCopy);
});

test('lineTotal calculates qty × unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 8500 }), 8500);
  assert.equal(lineTotal({ qty: 5, unitPrice: 1000 }), 5000);
  assert.equal(lineTotal({ qty: 2, unitPrice: 2500 }), 5000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 3000 }), 30000);
});

test('lineTotal returns whole cents', () => {
  assert.equal(typeof lineTotal({ qty: 1, unitPrice: 100 }), 'number');
  assert.ok(Number.isInteger(lineTotal({ qty: 1, unitPrice: 100 })));
});

test('invoiceTotals calculates subtotal from line totals', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, vatRate: 0 },
      { qty: 3, unitPrice: 2000, vatRate: 0 },
      { qty: 1, unitPrice: 500, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 2000 + 6000 + 500);
  assert.equal(totals.subtotal, 8500);
});

test('invoiceTotals.total equals subtotal when no discount or VAT', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, vatRate: 0 },
      { qty: 2, unitPrice: 500, vatRate: 0 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.total, totals.subtotal);
  assert.equal(totals.total, 2000);
});

test('invoiceTotals handles empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with created invoices', () => {
  const products = listProducts();
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: products[0].sku, qty: 2, discountPercent: 0 },
      { sku: products[1].sku, qty: 3, discountPercent: 0 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal =
    lineTotal({ qty: 2, unitPrice: products[0].unitPrice }) +
    lineTotal({ qty: 3, unitPrice: products[1].unitPrice });
  assert.equal(totals.subtotal, expectedSubtotal);
  // Total should include VAT: total = subtotal + vat
  assert.ok(totals.total >= expectedSubtotal);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('addLine requires draft status', () => {
  const invoice = {
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    status: 'sent',
    lines: [{ sku: firstProduct.sku, name: firstProduct.name, qty: 1, unitPrice: firstProduct.unitPrice, vatRate: firstProduct.vatRate }],
  };

  const result = addLine(invoice, { sku: listProducts()[1].sku, qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
