    ok: false,
    error: 'AMOUNT_INVALID',
  });

  assert.deepEqual(applyVoucher(invoice, { code: 'TEST', amount: 'abc' }), {
    ok: false,
    error: 'AMOUNT_INVALID',
  });
});

test('applyVoucher does not mutate input invoice', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  applyVoucher(invoice, { code: 'TEST', amount: 500 });

  assert.equal(Object.hasOwn(invoice, 'voucher'), false);
});

test('invoiceTotals includes voucher amount', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.voucher, 500);
});

test('invoiceTotals calculates total with voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'SAVE', amount: 500 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.equal(totals.total, totals.subtotal + totals.vat - totals.voucher);
});

test('invoiceTotals with discount, vat, and voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 100, discountPercent: 20 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'FINAL', amount: 1000 }).value;
  const totals = invoiceTotals(withVoucher);

  assert.ok(totals.discount > 0);
  assert.ok(totals.vat > 0);
  assert.equal(totals.voucher, 1000);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - totals.voucher);
});

test('invoiceTotals clamps total at 0 with large voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const totals1 = invoiceTotals(invoice);
  const largeVoucher = totals1.total + 10000;

  const withVoucher = applyVoucher(invoice, { code: 'MASSIVE', amount: largeVoucher }).value;
  const totals2 = invoiceTotals(withVoucher);

  assert.equal(totals2.total, 0);
});

test('invoiceTotals without voucher returns 0 voucher', () => {
  const invoice = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  }).value;

  const totals = invoiceTotals(invoice);

  assert.equal(totals.voucher, 0);
});

