test('removeLine does not mutate the input invoice', () => {
  const products = listProducts();
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: products[0].sku, qty: 1 },
      { sku: products[1].sku, qty: 2 },
    ],
  });
  const invoice = invoiceResult.value;
  const originalLength = invoice.lines.length;

  removeLine(invoice, products[0].sku);
  assert.equal(invoice.lines.length, originalLength);
});

test('issueInvoice requires draft status', () => {
  const invoice = {
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    status: 'issued',
    lines: [{ sku: firstProduct.sku, name: firstProduct.name, qty: 1, unitPrice: firstProduct.unitPrice, vatRate: firstProduct.vatRate }],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice assigns an invoice number', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, true);
  assert.equal(result.value.number, 'INV-2026-0001');
});

test('issueInvoice assigns sequential numbers', () => {
  const invoiceResult1 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  const invoice1 = invoiceResult1.value;

  const invoiceResult2 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-02-15',
    lines: [{ sku: firstProduct.sku, qty: 2 }],
  });
  const invoice2 = invoiceResult2.value;

  const result1 = issueInvoice(invoice1, []);
  assert.equal(result1.value.number, 'INV-2026-0001');

  const result2 = issueInvoice(invoice2, [result1.value.number]);
  assert.equal(result2.value.number, 'INV-2026-0002');
});

test('issueInvoice changes status to issued', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  const invoice = invoiceResult.value;
  assert.equal(invoice.status, 'draft');

  const result = issueInvoice(invoice, []);
  assert.equal(result.value.status, 'issued');
});

test('issueInvoice preserves invoice data', () => {
  const products = listProducts();
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-03-20',
    lines: [
      { sku: products[0].sku, qty: 2 },
      { sku: products[1].sku, qty: 3 },
    ],
  });
  const invoice = invoiceResult.value;

  const result = issueInvoice(invoice, []);
  assert.equal(result.value.customerId, firstCustomer.id);
  assert.equal(result.value.issueDate, '2026-03-20');
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, products[0].sku);
  assert.equal(result.value.lines[0].qty, 2);
  assert.equal(result.value.lines[1].sku, products[1].sku);
  assert.equal(result.value.lines[1].qty, 3);
});

test('issueInvoice does not mutate the input invoice', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1 }],
  });
  const invoice = invoiceResult.value;
  const originalStatus = invoice.status;

  issueInvoice(invoice, []);
  assert.equal(invoice.status, originalStatus);
  assert.equal(invoice.status, 'draft');
  assert.equal(Object.hasOwn(invoice, 'number'), false);
});

test('createInvoice accepts valid discountPercent', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 10 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 10);
});

test('createInvoice accepts decimal discounts', () => {
  const result = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 12.5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 12.5);
});

test('createInvoice accepts edge case discounts (0 and 100)', () => {
  const result0 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 0 }],
  });
  assert.equal(result0.ok, true);

  const result100 = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: firstProduct.sku, qty: 1, discountPercent: 100 }],
