test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: firstProduct.sku, qty: 5, discountPercent: 50 },
    ],
  });
  const invoice = invoiceResult.value;

  const totals = invoiceTotals(invoice);

  // VAT should be calculated on amount after discount
  assert.ok(totals.vat > 0);
  // Verify VAT is reasonable (approximately 50% * vatRate of line total)
  const lineTotal = firstProduct.unitPrice * 5;
  const afterDiscount = lineTotal * 0.5;
  const expectedVATRange = Math.round((afterDiscount * firstProduct.vatRate) / 100);
  // Allow 1 cent difference due to rounding differences
  assert.ok(Math.abs(totals.vat - expectedVATRange) <= 1);
});

